import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import { exit, fade, motionMs, snap, spring } from "../lib/motion";
import { cn } from "../lib/utils";

import styles from "./text.module.css";

// A closed region leaves the parent's gap behind until it unmounts; the collapse eats that gap
// with a matching negative margin so nothing snaps when `hidden` finally removes it.
const stackGap = (node: HTMLElement | null) => {
  const parent = node?.parentElement;
  if (!node?.previousElementSibling || !parent) return 0;
  const layout = getComputedStyle(parent);
  const vertical =
    layout.display.includes("grid") ||
    (layout.display.includes("flex") && layout.flexDirection.startsWith("column"));
  return vertical ? parseFloat(layout.rowGap) || 0 : 0;
};

export const AnimatedCollapse = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<"div"> & { open: boolean; lazy?: boolean }
>(({ open, lazy = false, children, className, style, ...props }, ref) => {
  const own = React.useRef<HTMLDivElement | null>(null);
  const [gap, setGap] = React.useState(0);
  const [present, setPresent] = React.useState(open);
  const [mounted, setMounted] = React.useState(!lazy || open);
  const [expanded, setExpanded] = React.useState(open);
  React.useEffect(() => {
    setGap(stackGap(own.current));
    const reducedMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (open) {
      setMounted(true);
      setPresent(true);
      if (reducedMotion) {
        setExpanded(true);
        return;
      }
      const frame = requestAnimationFrame(() => setExpanded(true));
      return () => cancelAnimationFrame(frame);
    }
    setExpanded(false);
    if (reducedMotion) {
      setPresent(false);
      return;
    }
    const timer = window.setTimeout(() => setPresent(false), motionMs.exit.moderate);
    return () => window.clearTimeout(timer);
  }, [open]);
  const reduced = useReducedMotion();
  const [settled, setSettled] = React.useState(open);
  React.useEffect(() => {
    if (!expanded) setSettled(false);
  }, [expanded]);
  const travel = reduced ? snap : expanded ? spring.moderate : exit.moderate;
  return (
    <motion.div
      ref={(node) => {
        own.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      data-slot="animated-collapse"
      data-open={expanded || undefined}
      className={cn(styles.collapse, className)}
      hidden={!present && !open}
      aria-hidden={!open || undefined}
      {...(!open ? { inert: "" } : {})}
      initial={false}
      animate={{ height: expanded ? "auto" : 0, marginBlockStart: expanded ? 0 : -gap }}
      transition={travel}
      onAnimationComplete={() => {
        if (expanded) setSettled(true);
      }}
      style={{ ...style, overflow: settled ? "visible" : "hidden" }}
      {...(props as Omit<
        typeof props,
        "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart"
      >)}
    >
      <motion.div
        className={styles.collapseInner}
        initial={false}
        animate={{ opacity: expanded ? 1 : 0 }}
        transition={expanded ? fade.enter : exit.fast}
      >
        {(!lazy || mounted || open) && children}
      </motion.div>
    </motion.div>
  );
});
AnimatedCollapse.displayName = "AnimatedCollapse";

.truncate {
  display: inline-block;
  position: relative;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  vertical-align: bottom;
}
.mono {
  font-family: var(--v4-font-mono, monospace);
}
.measure {
  position: absolute;
  width: max-content;
  visibility: hidden;
  pointer-events: none;
  inset-inline-start: 0;
}
.collapse {
  display: block;
}
.collapse[hidden] {
  display: none;
}
.collapseInner {
  min-height: 0;
}
.text {
  margin: 0;
  color: var(--v4-ink, var(--foreground));
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.small {
  margin: 0;
  color: var(--v4-text2, var(--muted-foreground));
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.muted {
  color: var(--v4-muted, var(--muted-foreground));
}
.measurePage {
  width: 100%;
  max-width: var(--v4-size-measure-page);
  margin-inline: auto;
  padding: var(--v4-space-content-section) var(--v4-space-40);
}
.measureForm {
  width: 100%;
  max-width: var(--v4-size-measure-form);
}
@media (max-width: 640px) {
  .measurePage {
    padding: var(--v4-space-20) var(--v4-space-16);
  }
}
.stack {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.inline {
  display: flex;
  min-width: 0;
}
.grid {
  display: grid;
  min-width: 0;
}
.stack > *,
.inline > *,
.grid > * {
  min-width: 0;
}
.container {
  width: 100%;
  min-width: 0;
  margin-inline: auto;
  max-width: var(--v4-size-measure-page);
}
.measureProse {
  width: 100%;
  min-width: 0;
  max-width: var(--v4-size-measure-prose);
}
.heading {
  margin: 0;
  color: var(--v4-ink, var(--foreground));
  font-family: var(--v4-heading-family);
  font-size: var(--v4-heading-size);
  line-height: var(--v4-heading-line);
  font-weight: var(--v4-heading-weight);
  letter-spacing: var(--v4-heading-tracking);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.heading[data-size="page"] {
  --v4-heading-family: var(--v4-type-title-lg-font-family);
  --v4-heading-size: var(--v4-type-title-lg-font-size);
  --v4-heading-line: var(--v4-type-title-lg-line-height);
  --v4-heading-weight: var(--v4-type-title-lg-font-weight);
  --v4-heading-tracking: var(--v4-type-title-lg-letter-spacing);
}
.heading[data-size="display"] {
  --v4-heading-family: var(--v4-type-display-font-family);
  --v4-heading-size: var(--v4-type-display-font-size);
  --v4-heading-line: var(--v4-type-display-line-height);
  --v4-heading-weight: var(--v4-type-display-font-weight);
  --v4-heading-tracking: var(--v4-type-display-letter-spacing);
}
.heading[data-size="section"] {
  --v4-heading-family: var(--v4-type-title-font-family);
  --v4-heading-size: var(--v4-type-title-font-size);
  --v4-heading-line: var(--v4-type-title-line-height);
  --v4-heading-weight: var(--v4-type-title-font-weight);
  --v4-heading-tracking: var(--v4-type-title-letter-spacing);
}
.heading[data-size="subsection"] {
  --v4-heading-family: var(--v4-type-title-sm-font-family);
  --v4-heading-size: var(--v4-type-title-sm-font-size);
  --v4-heading-line: var(--v4-type-title-sm-line-height);
  --v4-heading-weight: var(--v4-type-title-sm-font-weight);
  --v4-heading-tracking: var(--v4-type-title-sm-letter-spacing);
}
.meta {
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
  font-variant-numeric: tabular-nums;
  color: var(--v4-muted, var(--muted-foreground));
}
.meta.mono {
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
}
